<?php
require_once "../db.php";requireAdmin();$repo=new TimeSlotRepository($pdo);$spaces=(new SpaceRepository($pdo))->getAll();$error="";$message="";
if($_SERVER["REQUEST_METHOD"]==="POST"){$action=$_POST["action"]??"";$id=filter_input(INPUT_POST,"slot_id",FILTER_VALIDATE_INT);try{if($action==="delete"){if($id&&$repo->deleteIfUnused($id))$message="Time slot deleted.";else$error="Slots with pending or confirmed reservations cannot be deleted.";}else{$space=filter_input(INPUT_POST,"space_id",FILTER_VALIDATE_INT);$cap=filter_input(INPUT_POST,"capacity",FILTER_VALIDATE_INT);if(!$space||!$cap)throw new InvalidArgumentException("Choose a space and valid capacity.");$repo->save($action==="update"?$id:null,$space,trim($_POST["slot_date"]??""),trim($_POST["start_time"]??""),trim($_POST["end_time"]??""),$cap);$message=$action==="update"?"Time slot updated.":"Time slot created.";}}catch(Throwable $e){$error=$e->getMessage();}}
$editId=filter_input(INPUT_GET,"edit",FILTER_VALIDATE_INT);$editing=$editId?$repo->find($editId):null;$rows=$repo->all();
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Manage time slots | CoworkSpace</title><link rel="stylesheet" href="../assets/style.css"></head><body><header class="navbar"><div class="container nav-content"><a class="logo" href="index.php">Cowork<span>Admin</span></a><nav class="nav-links"><a href="index.php">Dashboard</a><a href="spaces.php">Spaces</a><a class="active" href="time-slots.php">Time slots</a><a href="users.php">Users</a><a href="../logout.php">Log out</a></nav></div></header><main class="section"><div class="container"><div class="section-heading"><div><span class="eyebrow">SCHEDULE</span><h1>Manage time slots</h1></div><a class="btn btn-outline" href="index.php">Back to dashboard</a></div><?php if($error):?><div class="alert error"><?=htmlspecialchars($error)?></div><?php endif;?><?php if($message):?><div class="alert success"><?=htmlspecialchars($message)?></div><?php endif;?><section class="panel"><h2><?=$editing?"Edit time slot":"Add a time slot"?></h2><form method="POST" class="form-grid"><?php if($editing):?><input type="hidden" name="slot_id" value="<?=(int)$editing["id"]?>"><?php endif;?><div class="form-group"><label>Space</label><select name="space_id" required><?php foreach($spaces as $s):?><option value="<?=(int)$s["id"]?>" <?=((int)($editing["space_id"]??0)===(int)$s["id"])?"selected":""?>><?=htmlspecialchars($s["name"])?> (max <?=$s["capacity"]?>)</option><?php endforeach;?></select></div><div class="form-group"><label>Date</label><input type="date" name="slot_date" min="<?=date("Y-m-d")?>" value="<?=htmlspecialchars($editing["slot_date"]??date("Y-m-d"))?>" required></div><div class="form-group"><label>Start time</label><input type="time" name="start_time" value="<?=htmlspecialchars(isset($editing["start_time"])?substr($editing["start_time"],0,5):"09:00")?>" required></div><div class="form-group"><label>End time</label><input type="time" name="end_time" value="<?=htmlspecialchars(isset($editing["end_time"])?substr($editing["end_time"],0,5):"10:00")?>" required></div><div class="form-group"><label>Capacity</label><input type="number" name="capacity" min="1" value="<?=(int)($editing["capacity"]??1)?>" required></div><div class="form-actions"><button class="btn" name="action" value="<?=$editing?"update":"create"?>"><?=$editing?"Save changes":"Add time slot"?></button><?php if($editing):?><a class="btn btn-outline" href="time-slots.php">Cancel edit</a><?php endif;?></div></form></section><section class="panel"><h2>All time slots</h2><?php if(!$rows):?><div class="empty-state compact"><p>No time slots have been added.</p></div><?php else:?><div class="table-wrapper"><table><thead><tr><th>Space</th><th>Date</th><th>Time</th><th>Seats</th><th>Active bookings</th><th>Actions</th></tr></thead><tbody><?php foreach($rows as $t):?><tr><td><?=htmlspecialchars($t["space_name"])?></td><td><?=htmlspecialchars($t["slot_date"])?></td><td><?=htmlspecialchars(substr($t["start_time"],0,5))?>-<?=htmlspecialchars(substr($t["end_time"],0,5))?></td><td><?=(int)$t["capacity"]?></td><td><?=(int)$t["active_count"]?></td><td class="actions"><a class="btn btn-small btn-outline" href="time-slots.php?edit=<?=(int)$t["id"]?>">Edit</a><form method="POST" onsubmit="return confirm('Delete this time slot?')"><input type="hidden" name="slot_id" value="<?=(int)$t["id"]?>"><button class="btn btn-small btn-danger" name="action" value="delete">Delete</button></form></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section></div></main><footer class="footer"><div class="container">CoworkSpace Admin</div></footer></body></html>
